    { id=20628, tab=2, tier=2, col=3, name="Rapid Killing", icon="ability_hunter_rapidkilling", maxRank=2, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Reduces the cooldown of your Rapid Fire ability by 1 min. In addition, after killing an opponent that yields experience or honor, your next Aimed Shot, Arcane Shot or Auto Shot causes 10% additional damage. Lasts 20 sec.", "Reduces the cooldown of your Rapid Fire ability by 2 min. In addition, after killing an opponent that yields experience or honor, your next Aimed Shot, Arcane Shot or Auto Shot causes 20% additional damage. Lasts 20 sec." }, localized={deDE={name="Schneller Tod", tooltip={ "Verringert die Abklingzeit Eurer Fähigkeit 'Schnellfeuer' um 1 Min. Zusätzlich verursacht Euer nächster 'Gezielter Schuss', 'Arkaner Schuss' oder 'Automatischer Schuss' nach dem Töten eines Gegners, der Erfahrung oder Ehre gewährt, 10% zusätzlichen Schaden. Hält 20 Sek. lang an.", "Verringert die Abklingzeit Eurer Fähigkeit 'Schnellfeuer' um 2 Min. Zusätzlich verursacht Euer nächster 'Gezielter Schuss', 'Arkaner Schuss' oder 'Automatischer Schuss' nach dem Töten eines Gegners, der Erfahrung oder Ehre gewährt, 20% zusätzlichen Schaden. Hält 20 Sek. lang an." }}} },
