    { id=20656, tab=3, tier=4, col=2, name="Counterattack", icon="ability_warrior_challange", maxRank=1, prereqTalent=20650, prereqPoints=20, wired=true, tooltip={ "A strike that becomes active after parrying an opponent's attack. This attack deals 40 damage and immobilizes the target for 5 sec. Counterattack cannot be blocked, dodged, or parried." }, grant={ [1]=948338 }, localized={deDE={name="Gegenangriff", tooltip={ "Ein Schlag, der nach dem Parieren eines gegnerischen Angriffs verfügbar wird. Dieser Angriff verursacht 40 Schaden und macht das Ziel 5 Sek. lang bewegungsunfähig. 'Gegenangriff' kann weder geblockt noch ausgewichen oder pariert werden." }}} },
    { id=20657, tab=3, tier=5, col=0, name="Resourcefulness", icon="ability_hunter_resourcefulness", maxRank=3, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Reduces the mana cost of all traps and melee abilities by 20% and reduces the cooldown of all traps by 2 sec.", "Reduces the mana cost of all traps and melee abilities by 40% and reduces the cooldown of all traps by 4 sec.", "Reduces the mana cost of all traps and melee abilities by 60% and reduces the cooldown of all traps by 6 sec." }, grant={ [1]=34491, [2]=34492, [3]=34493 }, localized={deDE={name="Einfallsreichtum", tooltip={ "Verringert die Manakosten aller Fallen und Nahkampffähigkeiten um 20% und die Abklingzeit aller Fallen um 2 Sek.", "Verringert die Manakosten aller Fallen und Nahkampffähigkeiten um 40% und die Abklingzeit aller Fallen um 4 Sek.", "Verringert die Manakosten aller Fallen und Nahkampffähigkeiten um 60% und die Abklingzeit aller Fallen um 6 Sek." }}} },
    { id=20658, tab=3, tier=5, col=2, name="Lightning Reflexes", icon="spell_nature_invisibilty", maxRank=5, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Increases your Agility by 3%.", "Increases your Agility by 6%.", "Increases your Agility by 9%.", "Increases your Agility by 12%.", "Increases your Agility by 15%." }, grant={ [1]=19168, [2]=19180, [3]=19181, [4]=24296, [5]=24297 }, localized={deDE={name="Blitzartige Reflexe", tooltip={ "Erhöht Eure Beweglichkeit um 3%.", "Erhöht Eure Beweglichkeit um 6%.", "Erhöht Eure Beweglichkeit um 9%.", "Erhöht Eure Beweglichkeit um 12%.", "Erhöht Eure Beweglichkeit um 15%." }}} },
    { id=20659, tab=3, tier=6, col=0, name="Thrill of the Hunt", icon="ability_hunter_thrillofthehunt", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Gives you a 33% chance to regain 40% of the mana cost of any shot when it critically hits.", "Gives you a 66% chance to regain 40% of the mana cost of any shot when it critically hits.", "Gives you a 100% chance to regain 40% of the mana cost of any shot when it critically hits." }, grant={ [1]=34497, [2]=34498, [3]=34499 }, localized={deDE={name="Jagdfieber", tooltip={ "Gewährt Euch eine Chance von 33%, bei einem kritischen Treffer eines beliebigen Schusses 40% seiner Manakosten zurückzuerhalten.", "Gewährt Euch eine Chance von 66%, bei einem kritischen Treffer eines beliebigen Schusses 40% seiner Manakosten zurückzuerhalten.", "Gewährt Euch eine Chance von 100%, bei einem kritischen Treffer eines beliebigen Schusses 40% seiner Manakosten zurückzuerhalten." }}} },
    { id=20660, tab=3, tier=6, col=1, name="Wyvern Sting", icon="inv_spear_02", maxRank=1, prereqTalent=20655, prereqPoints=30, wired=true, tooltip={ "A stinging shot that puts the target to sleep for 12 sec. Any damage will cancel the effect. When the target wakes up, the Sting causes 300 Nature damage over 12 sec. Only one Sting per Hunter can be active on the target at a time." }, grant={ [1]=948330 }, localized={deDE={name="Wyvernbiss", tooltip={ "Ein Stich, der das Ziel 12 Sek. lang einschläfert. Jeglicher Schaden hebt den Effekt auf. Wenn das Ziel aufwacht, verursacht der Stich im Verlauf von 12 Sek. 300 Naturschaden. Auf einem Ziel kann jeweils nur ein Stich pro Jäger aktiv sein." }}} },
    { id=20661, tab=3, tier=6, col=2, name="Expose Weakness", icon="ability_rogue_findweakness", maxRank=3, prereqTalent=20658, prereqPoints=30, wired=true, tooltip={ "Your ranged criticals have a 33% chance to apply an Expose Weakness effect to the target. Expose Weakness increases the attack power of all attackers against that target by 25% of your Agility for 7 sec.", "Your ranged criticals have a 66% chance to apply an Expose Weakness effect to the target. Expose Weakness increases the attack power of all attackers against that target by 25% of your Agility for 7 sec.", "Your ranged criticals have a 100% chance to apply an Expose Weakness effect to the target. Expose Weakness increases the attack power of all attackers against that target by 25% of your Agility for 7 sec." }, localized={deDE={name="Schwäche aufdecken", tooltip={ "Eure kritischen Fernkampftreffer haben eine Chance von 33%, den Effekt 'Schwäche aufdecken' auf das Ziel anzuwenden. Dieser erhöht die Angriffskraft aller Angreifer gegen dieses Ziel 7 Sek. lang um 25% Eurer Beweglichkeit.", "Eure kritischen Fernkampftreffer haben eine Chance von 66%, den Effekt 'Schwäche aufdecken' auf das Ziel anzuwenden. Dieser erhöht die Angriffskraft aller Angreifer gegen dieses Ziel 7 Sek. lang um 25% Eurer Beweglichkeit.", "Eure kritischen Fernkampftreffer haben eine Chance von 100%, den Effekt 'Schwäche aufdecken' auf das Ziel anzuwenden. Dieser erhöht die Angriffskraft aller Angreifer gegen dieses Ziel 7 Sek. lang um 25% Eurer Beweglichkeit." }}} },
    { id=20662, tab=3, tier=7, col=1, name="Master Tactician", icon="ability_hunter_mastertactitian", maxRank=5, prereqTalent=0, prereqPoints=35, wired=true, tooltip={ "Your successful ranged attacks have a 6% chance to increase your critical strike chance with all attacks by 2% for 8 sec.", "Your successful ranged attacks have a 6% chance to increase your critical strike chance with all attacks by 4% for 8 sec.", "Your successful ranged attacks have a 6% chance to increase your critical strike chance with all attacks by 6% for 8 sec.", "Your successful ranged attacks have a 6% chance to increase your critical strike chance with all attacks by 8% for 8 sec.", "Your successful ranged attacks have a 6% chance to increase your critical strike chance with all attacks by 10% for 8 sec." }, localized={deDE={name="Meister der Taktik", tooltip={ "Eure erfolgreichen Fernkampfangriffe haben eine Chance von 6%, Eure kritische Trefferchance mit allen Angriffen 8 Sek. lang um 2% zu erhöhen.", "Eure erfolgreichen Fernkampfangriffe haben eine Chance von 6%, Eure kritische Trefferchance mit allen Angriffen 8 Sek. lang um 4% zu erhöhen.", "Eure erfolgreichen Fernkampfangriffe haben eine Chance von 6%, Eure kritische Trefferchance mit allen Angriffen 8 Sek. lang um 6% zu erhöhen.", "Eure erfolgreichen Fernkampfangriffe haben eine Chance von 6%, Eure kritische Trefferchance mit allen Angriffen 8 Sek. lang um 8% zu erhöhen.", "Eure erfolgreichen Fernkampfangriffe haben eine Chance von 6%, Eure kritische Trefferchance mit allen Angriffen 8 Sek. lang um 10% zu erhöhen." }}} },
